import {API,escapeHtml as esc,markdown,searchSources,validateBackup,makeSystemPrompt,requestCompletion,safeUrl} from './core.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
let STORE='cathedra-integra-local-v2-device';let corpus,key='',busy=false,controller,attachment=null,activeId=null,selected=new Set(),timer;
let state={chats:[],progress:[],model:'',maxTokens:4096};
let provider='chatgpt',localSession=null,gptModel='',gptModels=[],loadingModels=false;
const effectiveModel=()=>provider==='chatgpt'?gptModel:state.model;
async function localApi(action,data={}){const r=await fetch('./api/chatgpt/'+action,{method:'POST',headers:{'Content-Type':'application/json','X-CI-CSRF':localSession?.csrf||''},body:JSON.stringify(data)});const d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível concluir a operação local.');return d;}
function renderLocal(){
 $('#provider-select').value=provider;$('#gpt-settings').hidden=provider!=='chatgpt';$('#settings-form').hidden=provider!=='openrouter';
 const accounts=localSession?.accounts||[];$('#gpt-account').innerHTML=accounts.length?accounts.map(a=>'<option value="'+esc(a.id)+'">'+esc(a.label)+'</option>').join(''):'<option value="">Nenhuma conta registrada</option>';
 if(localSession?.active)$('#gpt-account').value=localSession.active.id;
 $('#gpt-logout').hidden=!localSession?.connected;$('#gpt-login').hidden=!!localSession?.connected&&!!localSession?.planEnabled;
 $('#gpt-add').hidden=!accounts.length;
 $('#gpt-status').textContent=localSession?.connected?(localSession.planEnabled?'Conta conectada: '+localSession.active.label+'. Você está usando seu plano ChatGPT.':'Login concluído, mas falta autorizar o uso do plano. Continue with ChatGPT para revisar a permissão.'):'Continue with ChatGPT para autorizar o uso do seu plano nesta edição local.';
 $('#gpt-models-area').hidden=!localSession?.planEnabled;$('#plan-usage').hidden=provider!=='chatgpt'||!localSession?.planEnabled;renderConnection();
}
async function refreshLocal(switchStorage=true){
 const r=await fetch('./api/chatgpt/status');if(!r.ok)throw Error('Abra esta edição pelo servidor local, usando Iniciar-Cathedra.cmd.');const data=await r.json();if(switchStorage)persist();localSession=data;
 STORE='cathedra-integra-local-v2-'+(data.active?.id||'device');if(switchStorage){state={chats:[],progress:[],model:'',maxTokens:4096};load();activeId=null;selected.clear();attachment=null;$('#prompt').value='';renderChat();renderSources();renderSelected();renderCourse();renderAttachments();$('#model-input').value=state.model;$('#max-tokens').value=state.maxTokens;}
 gptModel='';gptModels=[];$('#gpt-model').innerHTML='';renderLocal();if(data.planEnabled)await loadGptModels();
}
async function loadGptModels(){if(loadingModels)return;loadingModels=true;$('#gpt-refresh-models').disabled=true;$('#gpt-status').textContent='Consultando os modelos da conta conectada…';try{const d=await localApi('models');gptModels=d.models;const saved=localStorage.getItem('ci-model-'+localSession.active.id);gptModel=gptModels.some(m=>m.id===saved)?saved:(gptModels[0]?.id||'');$('#gpt-model').innerHTML=gptModels.map(m=>'<option value="'+esc(m.id)+'">'+esc(m.name)+'</option>').join('');$('#gpt-model').value=gptModel;$('#gpt-status').textContent=gptModels.length?'Conta conectada: '+localSession.active.label+'. Você está usando seu plano ChatGPT.':'Nenhum modelo foi liberado para esta conta. Confira a elegibilidade e as permissões no ChatGPT.';}catch(e){gptModel='';gptModels=[];$('#gpt-model').innerHTML='';$('#gpt-status').textContent=e.message;}finally{loadingModels=false;$('#gpt-refresh-models').disabled=false;renderConnection();}}
async function startLogin(add=false){if(busy)return;$('#gpt-login').disabled=true;$('#gpt-add').disabled=true;try{const d=await localApi('login',{accountId:add?null:$('#gpt-account').value||null});const url=new URL(d.url);if(url.origin!=='https://auth.openai.com')throw Error('Endereço de login não reconhecido.');location.assign(url.href);}catch(e){$('#gpt-status').textContent=e.message;$('#gpt-login').disabled=false;$('#gpt-add').disabled=false;}}

function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;clearTimeout(timer);timer=setTimeout(()=>$('#toast').hidden=true,4500);}
function persist(){try{localStorage.setItem(STORE,JSON.stringify(state));}catch{toast('Armazenamento indisponível ou cheio. Exporte um backup para preservar os dados.');}}
function load(){try{const s=JSON.parse(localStorage.getItem(STORE));if(s){const valid=validateBackup({...s,version:1});state={...valid,model:typeof s.model==='string'?s.model:'',maxTokens:Number(s.maxTokens)>=256&&Number(s.maxTokens)<=16000?Number(s.maxTokens):4096};}}catch{toast('Não foi possível ler os dados salvos. Você pode importar um backup nas configurações.');}}
function download(text,name,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);}
const labels={exame:'Exame de consciência',oratorio:'Oratório e horas',inicio:'Visão geral',conversa:'Consultor teológico',biblioteca:'Biblioteca de fontes',catequese:'Percurso de catequese',configuracoes:'Configurações'};
function route(){let p=location.hash.slice(1);if(!labels[p])p='inicio';$$('.page').forEach(e=>e.hidden=e.id!=='page-'+p);$$('[data-page]').forEach(e=>e.classList.toggle('active',e.dataset.page===p));$('#crumb').textContent=labels[p];$('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');if(p==='conversa')renderChat();window.scrollTo(0,0);}
function current(){return state.chats.find(c=>c.id===activeId);}
function newChat(mode='consultor'){if(busy){toast('Interrompa a resposta antes de iniciar outra conversa.');return;}activeId=null;$('#mode').value=mode;selected.clear();attachment=null;renderAttachments();renderSelected();$('#prompt').value='';renderChat();location.hash='conversa';}
function renderHistory(){$('#history').innerHTML=state.chats.length?state.chats.slice(0,10).map(c=>`<button data-chat="${esc(c.id)}" title="${esc(c.title)}">${esc(c.title)}</button>`).join(''):'<p class="empty">Seu próximo estudo começa aqui.</p>';}
function renderChat(){const c=current();if(c)$('#mode').value=c.mode;$('#chat-model').textContent=effectiveModel()||'Modelo não selecionado';const messages=c?.messages||[];$('#messages').innerHTML=messages.length?messages.map((m,i)=>`<article class="message ${m.role}"><div class="message-label">${m.role==='user'?'Você':'✦ Cathedra Integra'}</div><div class="message-content">${markdown(m.content)}</div>${m.role==='assistant'?`<button data-copy="${i}">Copiar resposta</button>`:''}</article>`).join(''):'<div class="welcome"><img src="./assets/emblema.svg" alt=""><h2>Que verdade deseja aprofundar?</h2><p>Sou o Cathedra Integra, uma persona de IA que simula uma voz católica devota na orientação configurada. Podemos estudar, refletir e rezar juntos.</p><p>Conecte sua conta ChatGPT ou configure o OpenRouter nas configurações para começar.</p></div>';if(busy){const p=document.createElement('p');p.id='thinking';p.textContent='O Cathedra está preparando a resposta…';p.className='fine-print';$('#messages').append(p);}$('#messages').scrollTop=$('#messages').scrollHeight;renderHistory();}
function renderConnection(){const ready=provider==='chatgpt'?!!localSession?.planEnabled&&!!gptModel:!!key&&!!state.model;$('#provider-dot').classList.toggle('connected',ready);$('#connection-dot').classList.toggle('connected',ready);$('#provider-label').textContent=provider==='chatgpt'?(ready?'Usando plano ChatGPT':'Conectar ChatGPT'):(ready?'OpenRouter configurado':'Configurar OpenRouter');$('#chat-model').textContent=effectiveModel()||'Modelo não selecionado';$('#plan-usage').hidden=provider!=='chatgpt'||!localSession?.planEnabled;}
function renderSources(){const sources=searchSources(corpus.catalog.sources,$('#source-search').value,$('#theme').value);$('#results-count').textContent=sources.length+' fichas';$('#source-grid').innerHTML=sources.length?sources.map(s=>`<article class="source-card"><header><span>${esc(s.id)} / ${esc(s.theme)}</span><span>${esc(s.date||'')}</span></header><h3>${esc(s.title)}</h3><div class="author">${esc(s.author)} · ${esc(s.source_type)}</div><p>${esc(s.summary_pt)}</p><details><summary>Localizador e limites da fonte</summary><p><b>Localizador:</b> ${esc(s.locator)}</p><p><b>Limites:</b> ${esc(s.caution)}</p><p>Registro do catálogo: ${esc(s.verification)} · ${esc(s.checked_on)}. ${esc(s.storage)}</p></details><div class="actions">${safeUrl(s.url)?`<a href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">Abrir fonte original ↗</a>`:''}<button class="secondary" data-source="${esc(s.id)}">${selected.has(s.id)?'✓ Em contexto':'＋ Usar na conversa'}</button></div></article>`).join(''):'<p class="no-results">Nenhuma ficha encontrada. Experimente outro termo.</p>';}
function renderSelected(){$('#selected-sources').innerHTML=[...selected].map(id=>{const s=corpus.catalog.sources.find(s=>s.id===id);return `<button class="source-chip" data-source="${esc(id)}" title="Remover fonte">${esc(id)} · ${esc(s.title)} ×</button>`;}).join('');}
function renderCourse(){$('#course-grid').innerHTML=corpus.course.modules.map(m=>`<article class="course-card ${state.progress.includes(m.module)?'done':''}"><div class="course-number">${String(m.module).padStart(2,'0')}<small>${m.suggested_session_minutes} MIN · ${m.source_ids.join(', ')}</small></div><h3>${esc(m.title)}</h3><p>${esc(m.objective)}</p><div class="actions"><button class="secondary" data-lesson="${m.module}">Estudar este módulo ↗</button></div><label><input type="checkbox" data-progress="${m.module}" ${state.progress.includes(m.module)?'checked':''}> Marcar como estudado</label></article>`).join('');$('#course-progress').textContent=state.progress.length+' de 12 módulos estudados';$('#progress-fill').style.width=(state.progress.length/12*100)+'%';}
function renderAttachments(){$('#attachments').innerHTML=attachment?`<button id="remove-attachment">▤ ${esc(attachment.name)} ×</button>`:'';}
function exportText(){const c=current();if(!c?.messages.length){toast('Ainda não há conversa para exportar.');return;}download('# Cathedra Integra\n\n'+c.title+'\n\n'+c.messages.map(m=>'## '+(m.role==='user'?'Você':'Cathedra Integra')+'\n\n'+m.content).join('\n\n---\n\n'),'cathedra-conversa.md','text/markdown;charset=utf-8');}
async function submit(e){e.preventDefault();if(busy)return;if(provider==='chatgpt'?(!localSession?.planEnabled||!gptModel):(!key||!state.model)){toast(provider==='chatgpt'?'Conecte o ChatGPT e selecione um modelo disponível.':'Informe sua chave e selecione um modelo para conversar.');location.hash='configuracoes';return;}const text=$('#prompt').value.trim();if(!text)return;busy=true;controller=new AbortController();$('#send').hidden=true;$('#stop').hidden=false;$('#mode').disabled=true;$('#attachment').disabled=true;
 let c=current();if(!c){c={id:crypto.randomUUID(),title:text.slice(0,65),mode:$('#mode').value,messages:[]};state.chats.unshift(c);activeId=c.id;}c.mode=$('#mode').value;
 const attached=attachment?attachment.name+'\n'+attachment.content:null;const userContent=text+(attached?'\n\n[Texto anexado para análise]\n'+attached:'');c.messages.push({role:'user',content:userContent});$('#prompt').value='';attachment=null;renderAttachments();persist();renderChat();
 try{const prompt=makeSystemPrompt(corpus,c.mode,corpus.catalog.sources.filter(s=>selected.has(s.id)));const content=provider==='chatgpt'?(await (async()=>{const r=await fetch('./api/chatgpt/complete',{method:'POST',signal:controller.signal,headers:{'Content-Type':'application/json','X-CI-CSRF':localSession.csrf},body:JSON.stringify({model:gptModel,instructions:prompt,messages:c.messages.slice(-30)})});const d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível concluir a resposta.');return d;})()).content:await requestCompletion({key,model:state.model,maxTokens:state.maxTokens,signal:controller.signal,messages:[{role:'system',content:prompt},...c.messages.slice(-30)]});c.messages.push({role:'assistant',content});persist();}
 catch(err){$('#gpt-status').textContent=err.message;toast(err.name==='AbortError'?'Resposta interrompida. Sua mensagem foi preservada.':err.message);const p=document.createElement('p');p.className='message error';p.textContent=err.name==='AbortError'?'Geração interrompida.':err.message;$('#messages').append(p);$('#prompt').value=text;}
 finally{busy=false;controller=null;$('#send').hidden=false;$('#stop').hidden=true;$('#mode').disabled=false;$('#attachment').disabled=false;renderChat();}
}
async function loadModels(){const btn=$('#load-models');btn.disabled=true;$('#settings-status').textContent='Consultando modelos disponíveis…';try{const r=await fetch(API+'/models',{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error();const d=await r.json();$('#models').innerHTML=d.data.filter(m=>typeof m.id==='string').sort((a,b)=>a.id.localeCompare(b.id)).map(m=>`<option value="${esc(m.id)}">${esc(m.name||m.id)}</option>`).join('');$('#settings-status').textContent=d.data.length+' modelos carregados. Escolha um identificador ou informe-o manualmente.';}catch{$('#settings-status').textContent='Lista indisponível. Informe o identificador de um modelo do catálogo OpenRouter.';}finally{btn.disabled=false;}}
async function init(){try{const r=await fetch('./corpus.json');if(!r.ok)throw Error();corpus=await r.json();}catch{$('#main').textContent='Não foi possível carregar o acervo. Recarregue a página ou confira se corpus.json está junto do aplicativo.';return;}try{await refreshLocal(false);load();}catch(e){$('#gpt-status').textContent=e.message;$('#gpt-login').disabled=true;}$('#source-count').textContent=corpus.catalog.sources.length;const themes=[...new Set(corpus.catalog.sources.map(s=>s.theme))].sort();$('#theme').innerHTML+=[...themes].map(t=>`<option value="${esc(t)}">${esc(t)}</option>`).join('');$('#model-input').value=state.model;$('#max-tokens').value=state.maxTokens;
 $('#gpt-login').onclick=()=>startLogin();$('#gpt-add').onclick=()=>startLogin(true);$('#gpt-refresh-models').onclick=loadGptModels;
 $('#gpt-model').onchange=()=>{if(busy){$('#gpt-model').value=gptModel;return;}gptModel=$('#gpt-model').value;if(localSession?.active)localStorage.setItem('ci-model-'+localSession.active.id,gptModel);renderConnection();};
 $('#provider-select').onchange=()=>{if(busy){$('#provider-select').value=provider;toast('Interrompa a resposta antes de trocar a conexão.');return;}provider=$('#provider-select').value;renderLocal();};
 $('#gpt-account').onchange=async()=>{if(busy||loadingModels){renderLocal();toast('Aguarde a operação atual antes de trocar a conta.');return;}try{await localApi('select',{accountId:$('#gpt-account').value});await refreshLocal();}catch(e){toast(e.message);}};
 $('#gpt-logout').onclick=async()=>{controller?.abort();$('#gpt-logout').disabled=true;try{const d=await localApi('logout');await refreshLocal();$('#gpt-status').textContent=d.message;}catch(e){toast(e.message);}finally{$('#gpt-logout').disabled=false;}};
 const loginParams=new URLSearchParams(location.search);if(loginParams.has('login_error'))$('#gpt-status').textContent=loginParams.get('login_error');if(loginParams.get('login')==='success'&&localSession?.planEnabled)toast('Você está usando seu plano ChatGPT. Gerencie os limites nas configurações do ChatGPT.');if(loginParams.has('login')||loginParams.has('login_error'))history.replaceState(null,'',location.pathname+location.hash);
 $('#new-chat').onclick=()=>newChat();$('#start-conversation').onclick=()=>newChat();$('#about').onclick=()=>location.hash='configuracoes';$('#menu-toggle').onclick=()=>{$('#sidebar').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String($('#sidebar').classList.contains('open')));};
 document.addEventListener('click',async e=>{const t=e.target.closest('[data-target],[data-mode],[data-prompt],[data-chat],[data-source],[data-lesson],[data-copy]');if(!t)return;if(t.dataset.target){location.hash=t.dataset.target;}else if(t.dataset.mode){newChat(t.dataset.mode);}else if(t.dataset.prompt){if(busy)return;newChat();$('#prompt').value=t.dataset.prompt;$('#prompt').focus();}else if(t.dataset.chat){if(busy){toast('Interrompa a resposta antes de trocar de conversa.');return;}activeId=t.dataset.chat;attachment=null;renderAttachments();renderChat();location.hash='conversa';}else if(t.dataset.source){const id=t.dataset.source;if(selected.has(id))selected.delete(id);else if(selected.size<8)selected.add(id);else{toast('Selecione até oito fichas de cada vez.');return;}renderSources();renderSelected();}else if(t.dataset.lesson){if(busy)return;const m=corpus.course.modules.find(m=>m.module===Number(t.dataset.lesson));newChat('catequese');m.source_ids.forEach(id=>selected.add(id));renderSelected();renderSources();$('#prompt').value=`Quero estudar o módulo ${m.module}: ${m.title}. Objetivo: ${m.objective}. Tópicos: ${m.topics.join('; ')}. Exercício: ${m.practice}. Dê a primeira aula com fontes, perguntas e prática.`;$('#prompt').focus();}else if(t.dataset.copy){try{await navigator.clipboard.writeText(current().messages[Number(t.dataset.copy)].content);toast('Resposta copiada.');}catch{toast('Não foi possível copiar. Use Exportar texto.');}}});
 document.addEventListener('change',e=>{if(e.target.dataset.progress){const n=Number(e.target.dataset.progress);state.progress=e.target.checked?[...new Set([...state.progress,n])]:state.progress.filter(x=>x!==n);persist();renderCourse();}});
 $('#mode').onchange=()=>{const c=current();if(c){c.mode=$('#mode').value;persist();}};$('#source-search').oninput=renderSources;$('#theme').onchange=renderSources;$('#chat-form').onsubmit=submit;$('#prompt').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();$('#chat-form').requestSubmit();}};$('#stop').onclick=()=>controller?.abort();
 $('#attachment').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>80000){toast('Use um arquivo de texto com até 80 KB.');e.target.value='';return;}if(!/\.(txt|md|csv|json)$/i.test(f.name)){toast('Formato aceito: TXT, MD, CSV ou JSON.');return;}attachment={name:f.name,content:await f.text()};renderAttachments();e.target.value='';};$('#attachments').onclick=e=>{if(e.target.closest('#remove-attachment')){attachment=null;renderAttachments();}};
 $('#settings-form').onsubmit=e=>{e.preventDefault();const k=$('#api-key').value.trim();if(k&&!k.startsWith('sk-or-')){$('#settings-status').textContent='Confira a chave do OpenRouter (começa com sk-or-).';return;}if(k)key=k;state.model=$('#model-input').value.trim();state.maxTokens=Number($('#max-tokens').value);persist();$('#api-key').value='';$('#settings-status').textContent=key?'Configuração salva. A conexão será verificada ao enviar uma mensagem.':'Modelo salvo. Informe uma chave para conversar.';renderConnection();};$('#disconnect').onclick=()=>{controller?.abort();key='';$('#api-key').value='';renderConnection();$('#settings-status').textContent='Chave removida da memória.';};$('#load-models').onclick=loadModels;$('#export-chat').onclick=exportText;$('#print-chat').onclick=()=>{if(!current()?.messages.length){toast('Inicie uma conversa antes de salvar o PDF.');return;}window.print();};$('#backup').onclick=()=>download(JSON.stringify({version:1,chats:state.chats,progress:state.progress},null,2),'cathedra-backup.json','application/json');
 $('#restore').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(busy)throw Error('Interrompa a resposta antes de importar um backup.');if(f.size>10000000)throw Error('Use um backup de até 10 MB.');const data=validateBackup(JSON.parse(await f.text()));if(!confirm('Substituir as conversas e o progresso atuais por este backup?'))return;state={...state,...data};activeId=null;persist();renderChat();renderCourse();toast('Backup importado.');}catch(err){toast(err.message);}finally{e.target.value='';}};
 $('#clear-data').onclick=()=>{if(busy){toast('Interrompa a resposta antes de apagar os dados.');return;}if(confirm('Apagar todas as conversas e o progresso deste navegador? Exporte um backup antes, se desejar.')){key='';state={chats:[],progress:[],model:'',maxTokens:4096};activeId=null;selected.clear();attachment=null;persist();$('#model-input').value='';$('#api-key').value='';renderConnection();renderHistory();renderChat();renderCourse();renderAttachments();renderSelected();renderSources();toast('Dados apagados.');}};
 window.addEventListener('hashchange',route);renderHistory();renderSources();renderSelected();renderCourse();renderConnection();route();
}
init();
